Un **vecteur** est une paire de nombres (x, y). Les jeux s'en servent pour une **position** (où), une **vitesse** (à quelle allure, et dans quelle direction) et une **accélération** (comment la vitesse change). Chaque moteur et chaque bibliothèque mathématique en a un (`glm::vec2`, le `Vector2` de raylib, le `FVector2D` d'Unreal) ; ce cours fait grandir le `Vec2` de la leçon de C++ jusqu'à en faire un petit en-tête, et les extraits suivants l'incluent :

```cpp
// vec2.h
#pragma once
#include <cmath>
#include <ostream>

struct Vec2 {
    float x = 0, y = 0;

    Vec2& operator+=(Vec2 o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(Vec2 o) { x -= o.x; y -= o.y; return *this; }

    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalized() const {
        float len = length();
        return len > 0 ? Vec2{x / len, y / len} : *this;
    }
};

inline Vec2 operator+(Vec2 a, Vec2 b) { return {a.x + b.x, a.y + b.y}; }
inline Vec2 operator-(Vec2 a, Vec2 b) { return {a.x - b.x, a.y - b.y}; }
inline Vec2 operator*(Vec2 v, float k) { return {v.x * k, v.y * k}; }
inline Vec2 operator/(Vec2 v, float k) { return {v.x / k, v.y / k}; }
inline float dot(Vec2 a, Vec2 b) { return a.x * b.x + a.y * b.y; }

inline std::ostream& operator<<(std::ostream& os, Vec2 v) {
    return os << '(' << v.x << ", " << v.y << ')';
}
```

Ce ne sont que deux floats, donc on le passe **par valeur** partout, et `operator<<` l'affiche sous la forme `(x, y)`.

